"""CodeBench (iOS): default bpy UX — tqdm render progress + interactive preview.

Loaded automatically at Blender startup. Installs handlers so that, with NO user
code:

  * every render shows a **tqdm progress bar** — Blender fires `render_init` /
    `render_pre` / `render_stats` / `render_post` synchronously on the calling
    thread *during* the (blocking) render, so a handler can drive tqdm live; and
  * every render — and every saved ``.blend`` — opens the **interactive WebGL
    viewer** in CodeBench's preview (orbit / pinch-zoom / pan, plus a
    "Rendered ⟷ 3D" toggle to the photoreal image when a render exists).

The user writes no preview code: `bpy.ops.render.render()` shows a progress bar
then an orbitable result, and `bpy.ops.wm.save_as_mainfile(...)` shows the scene
interactively. Generator lives in ``codebench_blend_view`` (bundled at the
site-packages root). Failures are swallowed (e.g. when not inside CodeBench).

Note on GPU: Cycles' Metal device works on iOS, but the FIRST render of a session
compiles Metal kernels serially (~3 min) — there's no Blender callback during
that compile, so the bar won't move until sampling starts; kernels cache after.
"""

import bpy
import os
import sys
import tempfile
import time

from bpy.app.handlers import persistent

try:
    from tqdm import tqdm as _TQDM
except Exception:
    _TQDM = None

# Live progress-bar state + a timestamp so a save right after a render doesn't
# overwrite the (nicer, photoreal) render preview with a geometry-only one.
_state = {"t0": None, "sbar": None, "fbar": None}
_last_preview_t = [0.0]


def _close_bars():
    for k in ("sbar", "fbar"):
        b = _state.get(k)
        if b is not None:
            try:
                b.close()
            except Exception:
                pass
            _state[k] = None


# ── tqdm render progress ──────────────────────────────────────────────────

@persistent
def _render_init(*_args):
    _state["t0"] = time.time()
    print("[bpy] rendering… (first GPU render compiles Metal kernels ~3 min, then cached)",
          flush=True)
    if _TQDM and bpy.data.scenes:
        sc = bpy.data.scenes[0]
        frames = sc.frame_end - sc.frame_start + 1
        if frames > 1:
            try:
                _state["fbar"] = _TQDM(total=frames, desc="frames", unit="f",
                                       file=sys.stdout, dynamic_ncols=True)
            except Exception:
                _state["fbar"] = None


@persistent
def _render_pre(*_args):
    if _TQDM:
        try:
            _state["sbar"] = _TQDM(desc="  sampling", unit="upd", file=sys.stdout,
                                   dynamic_ncols=True, leave=False, mininterval=0.3)
        except Exception:
            _state["sbar"] = None


@persistent
def _render_stats(*_args):
    b = _state.get("sbar")
    if b is not None:
        try:
            b.update(1)
        except Exception:
            pass


@persistent
def _render_post(*_args):
    b = _state.get("sbar")
    if b is not None:
        try:
            b.close()
        except Exception:
            pass
        _state["sbar"] = None
    f = _state.get("fbar")
    if f is not None:
        try:
            f.update(1)
        except Exception:
            pass


# ── interactive preview ───────────────────────────────────────────────────

def _emit_interactive(render_png):
    """Build the interactive viewer for scene 0 and ship it; embed `render_png`
    behind the Rendered toggle if given. Uses bpy.data (context is restricted in
    handlers)."""
    try:
        scene = bpy.data.scenes[0] if bpy.data.scenes else None
        if scene is None:
            return
        import codebench_blend_view as cbv
        name = os.path.basename(bpy.data.filepath) or "scene.blend"
        html = cbv.build_view(scene, render_png_path=render_png, title=name)
        if html:
            cbv.emit(html)
            _last_preview_t[0] = time.time()
            print("✓ Blender: interactive 3D preview (drag to orbit · pinch to zoom)", flush=True)
    except Exception as ex:
        sys.stderr.write("[codebench_blend_preview] interactive preview failed: %r\n" % ex)


@persistent
def _render_complete(*_args):
    _close_bars()
    if _state.get("t0"):
        print("[bpy] render done in %.1fs" % (time.time() - _state["t0"]), flush=True)
    # Save the render result so it can sit behind the "Rendered" toggle.
    png = None
    try:
        img = bpy.data.images.get("Render Result")
        if img is not None:
            png = os.path.join(tempfile.gettempdir(), "cb_render_%d.png" % int(time.time() * 1000))
            img.save_render(png)
            if not (os.path.isfile(png) and os.path.getsize(png) > 0):
                png = None
    except Exception:
        png = None
    _emit_interactive(png)


@persistent
def _render_cancel(*_args):
    _close_bars()


@persistent
def _save_post(*_args):
    # If a render in the last 5 s already opened a preview (with the photoreal
    # image), keep it — don't replace it with a geometry-only view.
    if time.time() - _last_preview_t[0] < 5.0:
        return
    _emit_interactive(None)


_HANDLERS = (
    ("render_init", _render_init),
    ("render_pre", _render_pre),
    ("render_stats", _render_stats),
    ("render_post", _render_post),
    ("render_complete", _render_complete),
    ("render_cancel", _render_cancel),
    ("save_post", _save_post),
)


def register():
    for name, fn in _HANDLERS:
        h = getattr(bpy.app.handlers, name, None)
        if h is not None and fn not in h:
            h.append(fn)


def unregister():
    for name, fn in _HANDLERS:
        h = getattr(bpy.app.handlers, name, None)
        if h is not None and fn in h:
            h.remove(fn)
